graphics.css:
/* Election - party totals. A deep ink panel with one hairline of light along its top edge; each
   party reads left to right as code, name, bar, share, votes. The share is the headline figure,
   so it carries the weight; votes sit beside it in the dimmer tone. */

@font-face {
  font-family: 'Manrope';
  src: url("fonts/manrope.woff2") format("woff2");
  font-weight: 200 800;
  font-display: swap;
}

:root {
  --scale: 1;
  --accent: #3dd6c6;
  --panel-bg: #0c1828;
  --panel-bg-top: #14263b;
  --ink: #f3f6fa;
  --ink-dim: #93a6bd;
  --edge: rgba(255, 255, 255, 0.07);
  --track: rgba(255, 255, 255, 0.06);
  --prelim: #f2b84b;
  --font: 'Manrope', 'Segoe UI', Arial, sans-serif;
}

html, body {
  margin: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  background: transparent;
}

.pb-root {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  visibility: hidden;
  font-family: var(--font);
  color: var(--ink);
}

.pb-panel {
  position: relative;
  width: 1280px;
  padding: 44px 56px 30px;
  box-sizing: border-box;
  background: linear-gradient(180deg, var(--panel-bg-top) 0%, var(--panel-bg) 46%);
  border-radius: 6px;
  box-shadow: 0 30px 80px rgba(0, 6, 16, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.10);
  overflow: hidden;
}
.pb-panel::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 4px;
  background: linear-gradient(90deg, var(--accent), rgba(61, 214, 198, 0) 70%);
}

.pb-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  padding-bottom: 26px;
  margin-bottom: 14px;
  border-bottom: 1px solid var(--edge);
}
.pb-kicker {
  font-size: 19px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
}
.pb-title {
  margin-top: 8px;
  font-size: 48px;
  font-weight: 800;
  letter-spacing: -0.01em;
  line-height: 1.05;
}
.pb-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
}
.pb-status {
  padding: 6px 14px 7px;
  border-radius: 3px;
  background: rgba(242, 184, 75, 0.14);
  color: var(--prelim);
  font-size: 17px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.pb-counted {
  font-size: 20px;
  font-weight: 600;
  color: var(--ink-dim);
  font-variant-numeric: lining-nums tabular-nums;
}

.pb-rows {
  list-style: none;
  margin: 0;
  padding: 0;
}
.pb-row {
  display: grid;
  grid-template-columns: 112px 300px 1fr 128px 150px;
  align-items: center;
  height: 55px;
  border-bottom: 1px solid var(--edge);
}
.pb-row:last-child { border-bottom: 0; }

.pb-chip {
  position: relative;
  display: inline-flex;
  align-items: center;
  height: 34px;
  padding-left: 16px;
}
.pb-swatch {
  position: absolute;
  left: 0;
  top: 3px;
  width: 6px;
  height: 28px;
  border-radius: 2px;
  font-size: 0;
  background: var(--row-color, var(--accent));
}
.pb-code {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: 0.04em;
}
.pb-name {
  font-size: 22px;
  font-weight: 500;
  color: var(--ink-dim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  padding-right: 20px;
}
.pb-track {
  position: relative;
  height: 20px;
  margin-right: 28px;
  border-radius: 2px;
  background: var(--track);
  overflow: hidden;
}
.pb-bar {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 0;
  border-radius: 2px;
  background: var(--row-color, var(--accent));
}
.pb-share {
  text-align: right;
  font-size: 30px;
  font-weight: 800;
  font-variant-numeric: lining-nums tabular-nums;
}
.pb-votes {
  text-align: right;
  font-size: 21px;
  font-weight: 500;
  color: var(--ink-dim);
  font-variant-numeric: lining-nums tabular-nums;
}

.pb-foot {
  margin-top: 18px;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: rgba(147, 166, 189, 0.75);
}

graphics.js:
/* Election - party totals. SPX lifecycle; ES5 only (CasparCG 2.3's Chromium 71). A share
   arrives as text ("22.7%"); the bars are drawn against the largest share on the board, so the
   leader fills the track and every other bar keeps its true proportion to it.
   Every entrance tween names its end state, so a play() that interrupts another never
   ends hidden. */

(function () {
  var entrance = null;
  var onAir = false;

  function shareOf(text) {
    var n = parseFloat(String(text || '').replace(',', '.').replace(/[^0-9.]/g, ''));
    return isFinite(n) && n > 0 ? n : 0;
  }

  function rows() {
    return document.querySelectorAll('.pb-row');
  }

  function paintColours() {
    var swatches = document.querySelectorAll('.pb-swatch');
    for (var i = 0; i < swatches.length; i++) {
      var row = swatches[i].parentNode.parentNode;
      row.style.setProperty('--row-color', swatches[i].getAttribute('data-color') || '');
    }
  }

  function barWidths() {
    var list = rows();
    var widths = [];
    var top = 0;
    for (var i = 0; i < list.length; i++) {
      var s = shareOf(list[i].querySelector('.pb-share').textContent);
      widths.push(s);
      if (s > top) { top = s; }
    }
    for (var j = 0; j < widths.length; j++) {
      widths[j] = top > 0 ? (widths[j] / top) * 100 : 0;
    }
    return widths;
  }

  function drawBars(animate) {
    var list = rows();
    var widths = barWidths();
    for (var i = 0; i < list.length; i++) {
      var bar = list[i].querySelector('.pb-bar');
      if (animate) {
        gsap.to(bar, { width: widths[i] + '%', duration: 0.8, ease: 'power2.out', overwrite: true });
      } else {
        gsap.set(bar, { width: widths[i] + '%' });
      }
    }
  }

  window.update = function (data) {
    var parsed = typeof data === 'string' ? JSON.parse(data) : data;
    if (!parsed) { return; }
    for (var key in parsed) {
      var el = document.getElementById(key);
      if (!el) { continue; }
      if (el.hasAttribute('data-color')) {
        el.setAttribute('data-color', parsed[key]);
        el.textContent = '';
      } else {
        el.textContent = parsed[key];
      }
    }
    paintColours();
    // A count arriving on air moves the bars; before Take they are simply set.
    drawBars(onAir);
  };

  window.play = function () {
    if (entrance) { entrance.kill(); }
    paintColours();
    onAir = true;
    var widths = barWidths();
    entrance = gsap.timeline();
    entrance.set('#pb-root', { autoAlpha: 1 });
    entrance.fromTo('.pb-panel', { y: 26, autoAlpha: 0 }, { y: 0, autoAlpha: 1, duration: 0.55, ease: 'power3.out' }, 0);
    entrance.fromTo('.pb-head > *', { y: 12, autoAlpha: 0 }, { y: 0, autoAlpha: 1, duration: 0.45, ease: 'power2.out', stagger: 0.08 }, 0.15);
    entrance.fromTo('.pb-row', { x: -18, autoAlpha: 0 }, { x: 0, autoAlpha: 1, duration: 0.4, ease: 'power2.out', stagger: 0.04 }, 0.25);
    var list = rows();
    for (var i = 0; i < list.length; i++) {
      entrance.fromTo(list[i].querySelector('.pb-bar'), { width: '0%' }, { width: widths[i] + '%', duration: 0.9, ease: 'power3.out' }, 0.45 + i * 0.04);
    }
    entrance.fromTo('.pb-foot', { autoAlpha: 0 }, { autoAlpha: 1, duration: 0.4 }, 0.8);
  };

  window.stop = function () {
    onAir = false;
    if (entrance) { entrance.kill(); }
    gsap.to('.pb-panel', { y: 16, autoAlpha: 0, duration: 0.4, ease: 'power2.in' });
    gsap.to('#pb-root', { autoAlpha: 0, duration: 0.4, delay: 0.05, onComplete: function () {
      gsap.set('.pb-panel', { y: 0, autoAlpha: 1 });
    } });
  };

  window.next = function () {};

  function ready() { paintColours(); drawBars(false); }
  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', ready); } else { ready(); }
})();

